title Control flow
@Actor Reader
Reader.open() {
 Viewer.parse() {
  if(valid) {
   while(next) { Renderer.render() }
  } else { Viewer.showError() }
  par { Cache.write() }
  try { Storage.save() } catch(err) { Logger.warn() } finally { Viewer.finish() }
 }
 return result
}

